package com.elektoryk.scan.ui;

import android.app.Activity;import android.content.Intent;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.os.Bundle;import android.view.ViewGroup;import android.widget.*;
import com.elektoryk.scan.audio.ConsultationRecordingService;import com.elektoryk.scan.model.ObjectFlowState;import com.elektoryk.scan.storage.ObjectFlowRepository;

public class ClientBriefActivity extends Activity {
    private String projectId;private ObjectFlowRepository repo;private ObjectFlowState state;
    private EditText client,phone,address,note;private NumberStepper sockets,switches,lights,wallLights,panels,lan,cameras,budgetMin,budgetMax,passes;private ChoiceStrip workClass,visualization,confirmed,recordConsent,autoRecord;
    @Override protected void onCreate(Bundle b){super.onCreate(b);projectId=getIntent().getStringExtra("projectId");repo=new ObjectFlowRepository(this);state=repo.load(projectId);build();}
    private void build(){ScrollView s=new ScrollView(this);s.setBackgroundColor(Ui.BG);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(Ui.dp(this,14),Ui.dp(this,14),Ui.dp(this,14),Ui.dp(this,30));s.addView(root);
        root.addView(Ui.brandHeader(this,"ELEKTORYK • Бриф клієнта","Що клієнт реально хоче до скану і розрахунку.","BRIEF",true));
        root.addView(Ui.screenIntro(this,"КРОК 1","Спочатку зафіксуй побажання","Не треба одразу малювати. Зафіксуй орієнтовні точки, бюджет, клас виконання і чи потрібна ремонтна візуалізація. Після скану програма порівняє бажане з фактичним планом."),Ui.lpMatchWrap(this,10));
        LinearLayout who=Ui.card(this);who.addView(Ui.title(this,"Клієнт / об'єкт",18));client=input("Ім'я клієнта",state.clientName);phone=input("Телефон",state.clientPhone);address=input("Адреса / примітка про об'єкт",state.addressNote);who.addView(client,Ui.lpMatchWrap(this,6));who.addView(phone,Ui.lpMatchWrap(this,6));who.addView(address,Ui.lpMatchWrap(this,6));root.addView(who,Ui.lpMatchWrap(this,10));
        LinearLayout need=Ui.card(this);need.addView(Ui.title(this,"Орієнтовно хоче",18));sockets=num("розетки",state.requestedSockets,0,300);switches=num("вимикачі",state.requestedSwitches,0,150);lights=num("світильники",state.requestedLights,0,150);wallLights=num("бра / настінне світло",state.requestedWallLights,0,100);panels=num("щити",state.requestedPanels,0,10);lan=num("LAN / TV / слаботочка",state.requestedEthernet,0,100);cameras=num("камери",state.requestedCameras,0,100);need.addView(sockets);need.addView(switches);need.addView(lights);need.addView(wallLights);need.addView(panels);need.addView(lan);need.addView(cameras);root.addView(need,Ui.lpMatchWrap(this,10));
        LinearLayout money=Ui.card(this);money.addView(Ui.title(this,"Бюджет і клас",18));budgetMin=new NumberStepper(this,"грн від");budgetMin.configure(0,10000000,1000,0);budgetMin.setValue(state.budgetMin);money.addView(budgetMin);budgetMax=new NumberStepper(this,"грн до");budgetMax.configure(0,10000000,1000,0);budgetMax.setValue(state.budgetMax);money.addView(budgetMax,Ui.lpMatchWrap(this,5));workClass=new ChoiceStrip(this);workClass.setItems(new String[]{"ECONOMY","STANDARD","PREMIUM"},new String[]{"Економ","Стандарт","Преміум"},state.workClass.name());money.addView(workClass,Ui.lpMatchWrap(this,7));visualization=new ChoiceStrip(this);visualization.setItems(new String[]{"NO","YES"},new String[]{"Без ремонту","Потрібна візуалізація ремонту"},state.wantsRepairVisualization?"YES":"NO");money.addView(visualization,Ui.lpMatchWrap(this,7));root.addView(money,Ui.lpMatchWrap(this,10));
        LinearLayout scan=Ui.card(this);scan.addView(Ui.title(this,"Якість скану",18));passes=new NumberStepper(this,"проходів");passes.configure(1,8,1,0);passes.setValue(state.desiredScanPasses);scan.addView(passes);scan.addView(Ui.muted(this,"Рекомендовано 2 проходи в різних напрямках. Більше проходів корисно лише якщо вони додають нові кути, двері, ніші або закриті зони."),Ui.lpMatchWrap(this,5));root.addView(scan,Ui.lpMatchWrap(this,10));
        LinearLayout rec=Ui.card(this);rec.addView(Ui.title(this,"Аудіо домовленостей",18));rec.addView(Ui.muted(this,"Запис запускається тільки після зафіксованої згоди клієнта і системного дозволу Android. Під час запису в робочому екрані завжди видно індикатор."));recordConsent=new ChoiceStrip(this);recordConsent.setItems(new String[]{"NO","YES"},new String[]{"Згоди немає","Клієнт погодився на запис"},state.clientRecordingConsent?"YES":"NO");rec.addView(recordConsent,Ui.lpMatchWrap(this,7));autoRecord=new ChoiceStrip(this);autoRecord.setItems(new String[]{"NO","YES"},new String[]{"Запускати вручну","Автозапуск при вході в об'єкт"},state.autoRecordConsultation?"YES":"NO");rec.addView(autoRecord,Ui.lpMatchWrap(this,7));root.addView(rec,Ui.lpMatchWrap(this,10));
        note=input("Додаткові побажання / що обговорили",state.briefNote);root.addView(note,Ui.lpMatchWrap(this,10));confirmed=new ChoiceStrip(this);confirmed.setItems(new String[]{"NO","YES"},new String[]{"Ще уточнюємо","Бриф підтверджено"},state.briefConfirmed?"YES":"NO");root.addView(confirmed,Ui.lpMatchWrap(this,8));Button save=Ui.button(this,"Зберегти бриф");save.setOnClickListener(v->save());root.addView(save,Ui.lpMatchWrap(this,12));setContentView(s);}
    private EditText input(String hint,String value){EditText e=new EditText(this);e.setHint(hint);e.setHintTextColor(Ui.MUTED);e.setTextColor(Ui.TEXT);e.setText(value);e.setTextSize(15);e.setPadding(Ui.dp(this,12),Ui.dp(this,10),Ui.dp(this,12),Ui.dp(this,10));GradientDrawable g=new GradientDrawable();g.setColor(Ui.CARD_SOFT);g.setStroke(Ui.dp(this,1),Ui.STROKE);g.setCornerRadius(Ui.dp(this,12));e.setBackground(g);e.setSingleLine(false);return e;}
    private NumberStepper num(String unit,int value,int min,int max){NumberStepper n=new NumberStepper(this,unit);n.configure(min,max,1,0);n.setValue(value);return n;}
    private void save(){boolean hadConsent=state.clientRecordingConsent;state.clientName=client.getText().toString().trim();state.clientPhone=phone.getText().toString().trim();state.addressNote=address.getText().toString().trim();state.requestedSockets=sockets.getIntValue();state.requestedSwitches=switches.getIntValue();state.requestedLights=lights.getIntValue();state.requestedWallLights=wallLights.getIntValue();state.requestedPanels=panels.getIntValue();state.requestedEthernet=lan.getIntValue();state.requestedCameras=cameras.getIntValue();state.budgetMin=budgetMin.getValue();state.budgetMax=budgetMax.getValue();try{state.workClass=ObjectFlowState.WorkClass.valueOf(workClass.getSelectedKey());}catch(Exception ignored){}state.wantsRepairVisualization="YES".equals(visualization.getSelectedKey());state.desiredScanPasses=Math.max(1,passes.getIntValue());state.clientRecordingConsent="YES".equals(recordConsent.getSelectedKey());state.autoRecordConsultation="YES".equals(autoRecord.getSelectedKey())&&state.clientRecordingConsent;state.briefNote=note.getText().toString().trim();state.briefConfirmed="YES".equals(confirmed.getSelectedKey());repo.save(state);if(hadConsent&&!state.clientRecordingConsent)stopRecordingForThisProject();Toast.makeText(this,"Бриф збережено",Toast.LENGTH_SHORT).show();finish();}
    private void stopRecordingForThisProject(){android.content.SharedPreferences p=getSharedPreferences("consultation_recording",MODE_PRIVATE);if(!projectId.equals(p.getString("projectId",""))||p.getLong("startedAt",0)<=0)return;Intent i=new Intent(this,ConsultationRecordingService.class);i.setAction(ConsultationRecordingService.ACTION_STOP);try{startService(i);}catch(Exception ignored){}}
}
